import{_ as t,o as a,c as o,ak as r}from"./chunks/framework.sV-XtlWr.js";const u=JSON.parse('{"title":"Production checklist","description":"","frontmatter":{"title":"Production checklist","lang":"en-US"},"headers":[],"relativePath":"production-checklist.md","filePath":"production-checklist.md","lastUpdated":1788675926000}'),n={name:"production-checklist.md"};function i(s,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="production-checklist" tabindex="-1">Production checklist <a class="header-anchor" href="#production-checklist" aria-label="Permalink to &quot;Production checklist&quot;">​</a></h1><p>A fresh Piwi instance starts as an <strong>open dashboard with authentication off</strong> — right for localhost, wrong for a network. This is the one page that lists what to set before anyone else can reach it. Work down it before you put an instance on a shared address; the detail links go to the pages that explain each step.</p><h2 id="before-you-expose-it" tabindex="-1">Before you expose it <a class="header-anchor" href="#before-you-expose-it" aria-label="Permalink to &quot;Before you expose it&quot;">​</a></h2><ol><li><p><strong>Turn authentication on.</strong> Set <code>PIWI_AUTH_ENABLED=true</code> and a strong <code>PIWI_AUTH_SECRET</code> (session-cookie signing key). The server refuses to start with auth enabled and no secret, so this can&#39;t half-apply. See <a href="./authentication.html">Authentication</a>.</p></li><li><p><strong>Set the encryption key.</strong> Set <code>PIWI_SECRET_KEY</code> so the credentials you store in the dashboard — AI API keys, SCM tokens, webhook secrets — are encrypted with <strong>your</strong> key. Unset, Piwi falls back to a development key published in this repository, which is no protection at all. Generate either secret with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;console.log(require(&#39;node:crypto&#39;).randomBytes(32).toString(&#39;hex&#39;))&quot;</span></span></code></pre></div></li><li><p><strong>Terminate TLS.</strong> Always put the dashboard behind an HTTPS reverse proxy. Mind the two things a proxy gets wrong by default: <strong>upload size</strong> (trace and report uploads reach hundreds of MB) and <strong>SSE buffering</strong> (live runs and browser notifications use long-lived <code>text/event-stream</code> responses that must not be buffered). See <a href="./deployment.html#reverse-proxy-https">Deployment → Reverse proxy (HTTPS)</a>.</p></li><li><p><strong>Tell Piwi it&#39;s behind a proxy.</strong> Set <code>PIWI_TRUST_PROXY=true</code> so the per-client rate limits on the auth endpoints key on the real client address from <code>X-Forwarded-For</code> instead of pooling every request into the proxy&#39;s one address. Leave it off when clients connect directly — see the <a href="./configuration.html#authentication">configuration reference</a>.</p></li><li><p><strong>Persist and back up the data.</strong> Mount <code>/app/.data</code> (or your configured database and storage paths) on a persistent volume, and set up a backup before you accumulate history you care about. See <a href="./deployment.html#backups">Deployment → Backups</a>.</p></li><li><p><strong>Pin a version.</strong> Running <code>latest</code> lets an unattended <code>docker pull</code> move you across a breaking change. Pin an exact tag and bump it deliberately — migrations are forward-only, so the rollback path is <em>restore a backup</em>, not &quot;pull the old tag.&quot; See <a href="./upgrading.html">Upgrading</a>.</p></li></ol><p>Never leave the built-in development secrets in place on a real deployment.</p><h2 id="what-piwi-already-does-for-you" tabindex="-1">What Piwi already does for you <a class="header-anchor" href="#what-piwi-already-does-for-you" aria-label="Permalink to &quot;What Piwi already does for you&quot;">​</a></h2><p>The defaults are conservative, so the checklist above is short. Without any extra work:</p><ul><li>The container runs as a <strong>non-root</strong> user (<code>nodejs</code>, UID/GID 1001).</li><li>Passwords are hashed with <strong>scrypt</strong> and per-password salts; login, initial-setup and password-reset endpoints are <strong>rate-limited</strong> per client address (and failed logins per account), returning <code>429</code> with <code>Retry-After</code>.</li><li><strong>API keys</strong> are stored only as SHA-256 hashes and shown once, at creation — a leaked database yields no usable key.</li><li>Secrets supplied by <strong>environment variable</strong> are never written to the database and never returned by the API; the settings UI shows them read-only with a lock badge.</li><li>Stored credentials are encrypted with <strong>AES-256-GCM</strong> once <code>PIWI_SECRET_KEY</code> is set.</li><li>Database <strong>migrations are forward-only</strong> and run on startup; a failed migration stops the server rather than serving a half-migrated schema.</li></ul><h2 id="optional-and-worth-a-thought" tabindex="-1">Optional, and worth a thought <a class="header-anchor" href="#optional-and-worth-a-thought" aria-label="Permalink to &quot;Optional, and worth a thought&quot;">​</a></h2><ul><li><strong>Public share links</strong> are off by default (<code>PIWI_SHARE_LINKS_ENABLED</code>). If you turn them on, know that anyone with the link sees the execution or cluster without signing in — see <a href="./share-links.html">Share links</a>.</li><li><strong>Retention.</strong> Automatic pruning is opt-in; set <code>PIWI_RETENTION_DAYS</code> to cap how much run history you keep. See <a href="./storage.html#data-retention">Storage → Data retention</a>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./authentication.html">Authentication</a> — roles, OAuth, API keys</li><li><a href="./deployment.html">Deployment</a> — the reverse proxy, backups and the full install</li><li><a href="./privacy.html">Privacy &amp; data flow</a> — what is stored, and secrets at rest</li><li><a href="./configuration.html">Configuration reference</a> — every <code>PIWI_*</code> variable</li><li><a href="https://github.com/PiwiTests/platform/blob/main/SECURITY.md" target="_blank" rel="noreferrer">Security policy</a> — reporting a vulnerability</li></ul>',12)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
